#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    string smallestNumber(long long n) {
        if(n==1)return "1";
        string digits;
        for(int d=9;d>=2;--d) {
            while(n%d==0) {digits.push_back(char('0'+d));n/=d;}
        }
        if(n!=1)return "-1";
        reverse(digits.begin(),digits.end());
        return digits;
    }
};
